import{_ as a,d as e,e as o,x as p}from"./chunks/framework.BRr8VP3a.js";const h=JSON.parse('{"title":"为什么越来越依赖同一个人","description":"配置塑造能力、能力再影响配置是一条候选链，需要至少两轮材料。","frontmatter":{"title":"为什么越来越依赖同一个人","description":"配置塑造能力、能力再影响配置是一条候选链，需要至少两轮材料。"},"headers":[],"relativePath":"concepts/allocation-and-capability.md","filePath":"concepts/allocation-and-capability.md"}'),r={name:"concepts/allocation-and-capability.md"};function n(i,t,c,l,s,_){return e(),o("div",null,[...t[0]||(t[0]=[p('<h1 id="为什么越来越依赖同一个人" tabindex="-1">为什么越来越依赖同一个人 <a class="header-anchor" href="#为什么越来越依赖同一个人" aria-label="Permalink to &quot;为什么越来越依赖同一个人&quot;">​</a></h1><p>配置塑造能力、能力再影响配置是一条候选链，需要至少两轮材料。</p><p>关键任务每次都交给熟手，眼前完成率提高；别人始终缺少练习，后来更难接手。也可能先限制某些人的机会，再用形成的能力差距解释下一次排除。<a href="./../theory/part-07.html#section-7-6-1">§7.6.1</a>提出的是可反驳的候选机制。</p><p>链条为：<strong>配置任务与机会 → 实际练习 → 能力形成 → 下一轮配置</strong>。主张本案成立，至少检查两轮、可定位的配置决定、能力确实依赖实践形成、实践主要经由该配置取得、后一轮是否实际依据能力，以及差距或集中程度是否比起点扩大。能力的形成、保留与调用按§4.5取证；申请正式机制支持时，另按C10载体再生产路线取证。</p><p>竞争解释包括原有差距、报酬、权限、长训练周期、外部认证、选择或流失、一般稀缺，以及借能力话语掩饰偏好或利益。不能只因分配理由写着“能力”就当作因果证据。</p><p>教学情景：乙获得相称培训后达到与甲相当的能力，任务仍全部给甲。这可能提示其他排除机制，却削弱了“后续配置确因能力不同”这一段。应修订命中的链段，不能把反例改名为机制更强。</p><p>训练资源和交接条件应事前写明、可独立检查，观察窗口须匹配形成能力所需时间；资源同样紧张而配置规则不同的单位，可以提供进一步比较。得到不利结果后才说条件“不真实”，不能挽救旧主张。</p><p>机制即使成立，也不证明恶意、不可逆或先前成果无效。怎样调整配置、谁负担培训与冗余成本，仍是规范与权限问题。</p><p>继续阅读：<a href="./../theory/part-07.html#section-7-6">§7.6实践与再生产</a>、<a href="./../theory/part-08.html#section-8-6">§8.6承接</a>、<a href="./responsibility.html">承接与责任</a>。</p>',9)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
